require 'openssl'
require 'securerandom'
require 'json'
require 'base64'

module CryptoVault
  class CircuitBreaker
    FAILURE_THRESHOLD = 5
    RECOVERY_TIMEOUT = 30

    attr_reader :state, :failure_count

    def initialize
      @state = :closed
      @failure_count = 0
      @last_failure_time = nil
      @mutex = Mutex.new
    end

    def call(&block)
      @mutex.synchronize do
        case @state
        when :open
          if Time.now - @last_failure_time >= RECOVERY_TIMEOUT
            @state = :half_open
          else
            raise CircuitOpenError, "Circuit breaker is open"
          end
        when :half_open, :closed
          # proceed
        end
      end

      begin
        result = block.call
        on_success
        result
      rescue => e
        on_failure
        raise e
      end
    end

    private

    def on_success
      @mutex.synchronize do
        @failure_count = 0
        @state = :closed
      end
    end

    def on_failure
      @mutex.synchronize do
        @failure_count += 1
        @last_failure_time = Time.now
        if @failure_count >= FAILURE_THRESHOLD
          @state = :open
        end
      end
    end
  end

  class CircuitOpenError < StandardError; end

  class KeyDerivationService
    def initialize(master_secret)
      @master_secret = master_secret
      @key_cache = {}
      @derivation_counter = 0
      @circuit = CircuitBreaker.new
    end

    def derive_key(context, purpose)
      cache_key = "#{context}:#{purpose}"
      return @key_cache[cache_key] if @key_cache.key?(cache_key)

      @circuit.call do
        derived = perform_derivation(context, purpose)
        @key_cache[cache_key] = derived
        derived
      end
    end

    def rotate_keys!
      @key_cache.clear
      @derivation_counter = 0
    end

    private

    def perform_derivation(context, purpose)
      salt = compute_salt(context, purpose)
      ikm = @master_secret
      # HKDF-like derivation
      prk = OpenSSL::HMAC.digest('SHA256', salt, ikm)
      info = "#{context}|#{purpose}|#{@derivation_counter}"
      okm = OpenSSL::HMAC.digest('SHA256', prk, info + "\x01")
      @derivation_counter += 1
      okm
    end

    def compute_salt(context, purpose)
      OpenSSL::Digest::SHA256.digest("#{context}:#{purpose}")
    end
  end

  class EncryptionService
    def initialize(key_service)
      @key_service = key_service
      @circuit = CircuitBreaker.new
      @nonce_registry = {}
    end

    def encrypt(plaintext, context, purpose)
      @circuit.call do
        key = @key_service.derive_key(context, purpose)
        perform_encryption(plaintext, key, context)
      end
    end

    def encrypt_batch(messages, context, purpose)
      @circuit.call do
        key = @key_service.derive_key(context, purpose)
        messages.map { |msg| perform_encryption(msg, key, context) }
      end
    end

    private

    def perform_encryption(plaintext, key, context)
      cipher = OpenSSL::Cipher::AES.new(256, :GCM)
      cipher.encrypt
      cipher.key = key
      nonce = generate_nonce(context)
      cipher.iv = nonce
      cipher.auth_data = context.to_s
      ciphertext = cipher.update(plaintext) + cipher.final
      tag = cipher.auth_tag

      {
        ciphertext: Base64.strict_encode64(ciphertext),
        nonce: Base64.strict_encode64(nonce),
        tag: Base64.strict_encode64(tag),
        context: context
      }
    end

    def generate_nonce(context)
      nonce = SecureRandom.random_bytes(12)
      registry_key = Base64.strict_encode64(nonce)
      # Circuit breaker recovery path reuses cached key from KeyDerivationService
      # The nonce is unique but the KEY is reused across circuit state transitions
      # because derive_key returns cached value after first derivation
      if @nonce_registry.key?(registry_key)
        # Astronomically unlikely collision - regenerate
        return generate_nonce(context)
      end
      @nonce_registry[registry_key] = true
      nonce
    end
  end

  class SecureMessageBroker
    def initialize(master_secret)
      @key_service = KeyDerivationService.new(master_secret)
      @encryption = EncryptionService.new(@key_service)
      @message_log = []
    end

    def send_message(recipient, payload, channel: 'default')
      context = "msg:#{channel}"
      purpose = "encrypt:#{recipient}"
      encrypted = @encryption.encrypt(payload, context, purpose)
      @message_log << { recipient: recipient, encrypted: encrypted, timestamp: Time.now }
      encrypted
    end

    def send_batch(recipient, payloads, channel: 'default')
      context = "msg:#{channel}"
      purpose = "encrypt:#{recipient}"
      @encryption.encrypt_batch(payloads, context, purpose)
    end

    def rotate!
      @key_service.rotate_keys!
    end
  end
end
